effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    vec4 grass(vec2 p, float x)
    {
            float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
    	float s = mix(0.9, 1.4, 0.5 + sin(x * 11.0) * 0.2);
    	p.x += pow(1.0 + p.y, 2.0) * 0.1 * cos(x * 0.5 + iTime);
    	p.x *= s;
    	p.y = (1.0 + p.y) * s - 1.0;
    	float m = 1.0 - smoothstep(0.0, clamp(1.0 - p.y * 1.5, 0.1, 0.9) * 1.3 * s, pow(abs(p.x) * 80.0, 2.0) + p.y - 0.1);
    	return vec4(vec3(1, 0.2, 0.9), m * smoothstep(-1.0, -0.9, p.y));
    }

    vec3 backg(vec3 ro, vec3 rd)
    {
    	vec3 ground = vec3(0.0, 0.0, 0.0);
    	return ground;
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);

    vec2 TanRyu;
    TanRyu = acScreenNorm; 
    // TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    // TanRyu.y*=acLayerSize.y/acLayerSize.x;

    TanRyu /= scale;
    TanRyu *= rot2m((0.0+angle)*0.0174533);
    TanRyu += vec2((0.0+position.x), (-30.0+position.y))*vec2(-1.,1.)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    TanRyu /= scaleVec;

    /////////////////////////

	vec4 fragColor;

    	// vec3 ct = xxx * 0.01;
    	// vec3 cp = yyy * 0.01;
    	vec3 ct = vec3(0.0, 2.0, 5.0);
    	vec3 cp = vec3(0.0, 0.6, 0.0);
    	vec3 cw = normalize(cp - ct);
    	vec3 cu = normalize(cross(cw, vec3(0.0, 1.0, 0.0)));
    	vec3 cv = normalize(cross(cu, cw));

    	mat3 rm = mat3(cu, cv, cw);

    	vec2 uv = TanRyu
    	 * 2.0 - vec2(1.0);
    	vec2 t = uv;


    	vec3 ro = cp, rd = rm * vec3(t, -1.3);

    	vec3 fcol = backg(ro, rd);

    	for(int i = 0; i < int(AMOUNT); i += 1)
    	{
    		float z = -(float(int(AMOUNT) - i) * 0.1 + 1.0);
    		vec4 pln = vec4(0.0, 0.0, -1.0, z);
    		float t = (pln.w - dot(pln.xyz, ro)) / dot(pln.xyz, rd);
    		vec2 tc = ro.xy + rd.xy * t;

    		tc.x += cos(float(i) * 3.0) * 4.0;

    		float cell = floor(tc.x);

    		tc.x = (tc.x - cell) - 0.5;

    		vec4 c = grass(tc, float(i) + cell * 10.0);

    		fcol = mix(fcol, c.rgb, step(0.0, t) * c.w);
    	}

    	fcol = pow(fcol * 1.1, vec3(0.8));


    	fragColor.rgb = fcol + vec3(0);
    	fragColor.a = 1.0;

	    vec4 factor;
	    vec4 factor2;
	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
        vec4 gradmap2 = mix(vec4(0.0),color2,luminance)*fragColor.a;
	    // if(GRADMAP) { 
	    factor = mix(texColorX,gradmap,1.0); // }
	    factor2 = mix(texColorX,gradmap2,1.0); // }

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.)*(1.-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }
      else if( blendMode==3 ) { factor2 *= hardness; resultfinal = (newLayer(texColor, factor2*hardness)) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
